class Solution:
    def findReplaceString(self, s: str, indices: List[int], sources: List[str], targets: List[str]) -> str:
        mp = {}
        for i, idx in enumerate(indices):
            if s.startswith(sources[i], idx):
                mp[idx] = i
        res = []
        i = 0
        while i < len(s):
            if i in mp:
                j = mp[i]
                res.append(targets[j])
                i += len(sources[j])
            else:
                res.append(s[i])
                i += 1
        return ''.join(res)

