class Solution {
public:
    string findReplaceString(string s, vector<int>& indices, vector<string>& sources, vector<string>& targets) {
        unordered_map<int,int> mp;
        int n = s.size();
        for (int i = 0; i < (int)indices.size(); i++) {
            int idx = indices[i];
            if (idx + sources[i].size() <= n && s.compare(idx, sources[i].size(), sources[i]) == 0)
                mp[idx] = i;
        }
        string res;
        for (int i = 0; i < n;) {
            auto it = mp.find(i);
            if (it != mp.end()) {
                res += targets[it->second];
                i += sources[it->second].size();
            } else {
                res += s[i++];
            }
        }
        return res;
    }
};

