class Solution {
    public String findReplaceString(String s, int[] indices, String[] sources, String[] targets) {
        Map<Integer, Integer> mp = new HashMap<>();
        int n = s.length();
        for (int i = 0; i < indices.length; i++) {
            int idx = indices[i];
            if (idx + sources[i].length() <= n && s.startsWith(sources[i], idx))
                mp.put(idx, i);
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n;) {
            Integer j = mp.get(i);
            if (j != null) {
                sb.append(targets[j]);
                i += sources[j].length();
            } else {
                sb.append(s.charAt(i++));
            }
        }
        return sb.toString();
    }
}

