class Solution {
public:
    string findReplaceString(string s, vector<int>& indices, vector<string>& sources, vector<string>& targets) {
        vector<int> order(indices.size());
        iota(order.begin(), order.end(), 0);
        sort(order.begin(), order.end(), [&](int a, int b){ return indices[a] > indices[b]; });
        for (int i : order) {
            int idx = indices[i];
            if (idx + sources[i].size() <= s.size() && s.compare(idx, sources[i].size(), sources[i]) == 0)
                s.replace(idx, sources[i].size(), targets[i]);
        }
        return s;
    }
};

