/**
 * @param {string} s
 * @param {number[]} indices
 * @param {string[]} sources
 * @param {string[]} targets
 * @return {string}
 */
var findReplaceString = function(s, indices, sources, targets) {
    const arr = [...s];
    const order = [...Array(indices.length).keys()].sort((a, b) => indices[b] - indices[a]);
    for (const i of order) {
        const idx = indices[i];
        const src = sources[i];
        if (arr.slice(idx, idx + src.length).join('') === src) {
            arr.splice(idx, src.length, ...targets[i]);
        }
    }
    return arr.join('');
};
